// Modus setzen und die hochgeladene Audiodatei unter dem Namen "audio" bereitstellen
return $input.all().map(item => {
  const bin = item.binary || {};
  const keys = Object.keys(bin);
  const out = { json: { ...item.json, modus: 'termin', hat_audio: keys.length > 0 } };
  if (keys.length) out.binary = { audio: bin[keys[0]] };
  return out;
});

// ================= KONFIGURATION: hier anpassen =================
const cfg = {
  // Modell für Textarbeit. Die Basis-Adresse steht NICHT hier, sondern in der
  // Zugangsdatei des OpenAI-Knotens ("Base URL"). Anbieter wechseln heißt also:
  // dort eine andere Adresse eintragen, z.B. https://chat.kiconnect.nrw/api/v1 für THKI,
  // und hier den passenden Modellnamen. Der Ablauf selbst bleibt unverändert.
  llm_model: 'gpt-4.1',
  // Mail über Gmail: Absender ist das im Gmail-Knoten verbundene Konto.
  // Hier steht nur, wie der Absender im Postfach heißen soll, und wer die Mail bekommt.
  absender_name: 'C3, Claude Code Club',
  empfaenger: 'dekanat@example.org',
  pruefer: 'dekanat@example.org',
  // Google Kalender: 'primary' ist der Hauptkalender des verbundenen Kontos.
  // Zugangsdaten werden im Knoten selbst gewählt, sie stehen bewusst nicht in dieser Datei.
  kalender_id: 'primary',
  // Prüfschleife
  max_versuche: 3,
  max_worte: 250,
};
return $input.all().map(item => {
  const out = { json: { ...item.json, cfg } };
  if (item.binary) out.binary = item.binary;
  return out;
});

const k = $('Konfiguration').first().json;
// Der Transkriptionsknoten gibt das Ergebnis je nach Fassung unterschiedlich zurück.
// Defensiv lesen, damit ein Versionswechsel den Vortrag nicht kippt.
const gesprochen = $json.text ?? $json.transcript ?? $json.data?.text ?? '';
const transkript = String(gesprochen || k['Oder als Text'] || '').trim();
if (!transkript) throw new Error('Weder Sprachnachricht noch Text erhalten. Prüfen: Hat der Knoten Transkribieren ein Feld text geliefert? Sonst das Textfeld des Formulars nutzen.');
return [{ json: { transkript } }];

const heute = new Date().toISOString().slice(0, 10);
const system = `Du extrahierst Termindaten aus einer gesprochenen Nachricht eines Dekanats.
Antworte ausschließlich mit einem JSON-Objekt ohne weiteren Text:
{"titel": "", "datum": "JJJJ-MM-TT", "uhrzeit": "HH:MM", "ort": "", "teilnehmerkreis": "", "rueckmeldung_bis": "JJJJ-MM-TT", "hinweise": ""}
Regeln:
- Relative Angaben ("nächsten Donnerstag") rechnest du vom heutigen Datum ${heute} aus um.
- Unbekannte Felder bleiben leere Zeichenketten. Erfinde nichts.
- Keine Namen von Einzelpersonen in "teilnehmerkreis", nur Gruppen.`;
return [{ json: { transkript: $json.transkript, system, user: $json.transkript } }];

function kiText(j) {
  if (typeof j === 'string') return j;
  for (const k of ['content', 'text', 'output_text', 'message']) {
    const v = j?.[k];
    if (typeof v === 'string') return v;
    if (v && typeof v === 'object' && typeof v.content === 'string') return v.content;
  }
  if (Array.isArray(j?.output)) {
    const t = j.output.flatMap(o => (o.content || [])).map(c => c?.text).filter(Boolean).join('\n');
    if (t) return t;
  }
  return JSON.stringify(j);
}

const antwort = kiText($json);
const roh = antwort.replace(/```json|```/g, '').trim();
let t;
try { t = JSON.parse(roh); } catch (e) { throw new Error('Die KI hat kein gültiges JSON geliefert: ' + roh.slice(0, 200)); }
for (const f of ['titel', 'datum', 'uhrzeit', 'ort', 'teilnehmerkreis', 'rueckmeldung_bis', 'hinweise']) t[f] = String(t[f] ?? '').trim();
if (!t.titel) throw new Error('Kein Titel erkannt.');
if (t.datum && !/^\d{4}-\d{2}-\d{2}$/.test(t.datum)) throw new Error('Datum nicht im Format JJJJ-MM-TT: ' + t.datum);
const tag = (t.datum || new Date().toISOString().slice(0, 10)).replace(/-/g, '');
// Für den Kalendereintrag: Beginn aus Datum und Uhrzeit, Ende eine Stunde später.
// Bewusst ohne Zeitzonen-Kürzel: n8n legt die Zeitzone des Workflows zugrunde (Europe/Berlin).
const kal_datum = t.datum || new Date().toISOString().slice(0, 10);
const kal_zeit = /^\d{2}:\d{2}$/.test(t.uhrzeit) ? t.uhrzeit : '09:00';
const start_iso = kal_datum + 'T' + kal_zeit + ':00';
const end_iso = new Date(Date.parse(start_iso + 'Z') + 3600000).toISOString().slice(0, 19);
const termin_id = 'T-' + tag + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: {
  termin_id, titel: t.titel, datum: t.datum, uhrzeit: t.uhrzeit, ort: t.ort,
  teilnehmerkreis: t.teilnehmerkreis, rueckmeldung_bis: t.rueckmeldung_bis, hinweise: t.hinweise,
  start_iso, end_iso,
  transkript: $('Transkript übernehmen').first().json.transkript, erstellt_am: new Date().toISOString(),
} }];

// Die Data Table hat feste Spalten. Der Knoten übernimmt die Felder automatisch,
// deshalb hier nur genau die Spalten weitergeben, die es in der Tabelle gibt.
// start_iso und end_iso bleiben draußen, die liest der Kalender direkt aus 'Termin prüfen'.
const t = $('Termin prüfen').first().json;
const spalten = ['termin_id', 'titel', 'datum', 'uhrzeit', 'ort', 'teilnehmerkreis', 'rueckmeldung_bis', 'hinweise', 'transkript', 'erstellt_am'];
const zeile = {};
for (const s of spalten) zeile[s] = t[s] ?? '';
return [{ json: zeile }];

// Auswahlwerte für Airtable: links steht, was im Formular steht, rechts der
// Wert der Auswahlliste. Genau diese Schreibweise in Airtable anlegen, sonst
// legt typecast bei jeder Abweichung eine neue Option an.
const KATEGORIE = {
  'Noch gar nicht benutzt': 'Noch nicht',
  'Ein paar Mal ausprobiert': 'Ausprobiert',
  'Nutze es regelmäßig': 'Regelmäßig',
  'Baue schon eigene Sachen damit': 'Baue selbst',
  'Grundlagen und Datenschutz: was darf ich hineingeben?': 'Grundlagen und Datenschutz',
  'Claude auf meine Arbeit einstellen': 'Claude einstellen',
  'Eigene Skills bauen': 'Eigene Skills',
  'Abläufe, die ohne mich weiterlaufen': 'Abläufe automatisieren',
  'Viele Dokumente durchsuchbar machen': 'Dokumente durchsuchbar',
  'Im Team zusammenarbeiten': 'Team-Zusammenarbeit',
  'Werkstatt an meinem eigenen Fall': 'Eigener Fall',
  'Lehre': 'Lehre',
  'Verwaltung und Dekanat': 'Verwaltung',
  'Studierendenservice': 'Service',
  'Leitung': 'Leitung',
  'Forschung': 'Forschung',
  'Sonstiges': 'Sonstiges',
  'Weiß nicht, wo ich anfangen soll': 'Kein Einstieg',
  'Unsicher beim Datenschutz': 'Datenschutz unklar',
  'Keine Zeit zum Einarbeiten': 'Keine Zeit',
  'Zweifel, ob das Ergebnis taugt': 'Zweifel an Qualität',
  'Unklar, ob ich das darf': 'Erlaubnis unklar',
  'Nichts, ich bin schon dabei': 'Schon dabei',
  'Heute hat mir gereicht': 'Hat gereicht',
  'Ein weiterer Termin': 'Ein weiterer Termin',
  'Zwei bis drei Blöcke': 'Zwei bis drei Blöcke',
  'Regelmäßig, als Reihe': 'Regelmäßige Reihe',
  'Weiß ich noch nicht': 'Noch unklar',
};
// Unbekanntes bleibt unverändert stehen: Dann sieht man in Airtable sofort,
// dass ein Formularfeld geändert wurde, statt dass still falsch zugeordnet wird.
const kat = (wert) => KATEGORIE[String(wert || '').trim()] ?? String(wert || '').trim();
const k = $('Konfiguration').first().json;
const aufgaben = String(k['Welche Aufgaben wiederholen sich bei Ihnen? Gern mehrere, eine pro Zeile.'] || '')
  .split(/\r?\n/).map(z => z.replace(/^[\s\-*\u2022\d.)]+/, '').trim()).filter(Boolean).slice(0, 5);
const termine = $('Tabelle termine lesen').all().map(i => i.json).filter(t => t.termin_id);
termine.sort((a, b) => String(b.erstellt_am).localeCompare(String(a.erstellt_am)));
const termin_id = termine.length ? termine[0].termin_id : 'ohne-termin';
const rueckmeldung_id = 'R-' + (Date.now().toString(36).slice(-3) + Math.random().toString(36).slice(2, 4)).toUpperCase();
// Genau die Spalten der Tabelle 'rueckmeldungen', nichts darueber hinaus.
// Wichtig: Die Aufgabenliste geht nur als Text hinaus (kommentar) und als Zahl
// (anzahl_aufgaben). Data Tables und Airtable nehmen keine Listen an, ein Array
// bricht den Knoten mit 'unexpected array input' ab.
const zeile = {
  rueckmeldung_id, termin_id,
  antwort: kat(k['Wie soll es weitergehen?'] || 'Weiß ich noch nicht'),
  // Mehrere Aufgaben je Person: an Zeilenumbruechen trennen, Aufzaehlungszeichen
  // abschneiden, leere Zeilen weg. Fuenf reichen, danach wird es eine Wunschliste.
  kommentar: aufgaben.join('\n'),
  anzahl_aufgaben: aufgaben.length,
  bereich: kat(k['Aus welchem Bereich kommen Sie?']),
  hindernis: kat(k['Was hält Sie bisher davon ab?']),
  erfahrung: kat(k['Wie weit sind Sie mit Claude?'] || 'Noch gar nicht benutzt'),
  thema: kat(k['Welches Thema interessiert Sie am meisten?']),
  sonstiges: String(k['Noch etwas? (optional)'] || '').trim(),
  name: String(k['Name (optional)'] || '').trim() || 'anonym',
  eingang: new Date().toISOString(),
};
// Sicherung fuer spaetere Aenderungen: kommt doch einmal eine Liste herein,
// wird daraus Text, statt dass der Lauf mitten in der Vorfuehrung abbricht.
for (const [feld, wert] of Object.entries(zeile)) {
  if (Array.isArray(wert)) zeile[feld] = wert.join('\n');
}
return [{ json: zeile }];

// Eine Zeile je genannter Aufgabe. Der Rückmeldungs-Datensatz behält die Aufgaben
// als Text (Feld kommentar); hier entsteht zusätzlich der Ideenspeicher, in dem
// sich einzelne Aufgaben filtern, gruppieren und zählen lassen.
// Läuft der Zweig ohne Aufgaben, kommt kein Datensatz heraus und der Lauf endet still.
const r = $('Rückmeldung aufbereiten').first().json;
const aufgaben = String(r.kommentar || '').split(/\r?\n/).map(z => z.trim()).filter(Boolean);
return aufgaben.map((aufgabe, i) => ({ json: {
  idee_id: r.rueckmeldung_id + '-' + (i + 1),
  rueckmeldung_id: r.rueckmeldung_id,
  termin_id: r.termin_id,
  aufgabe,
  bereich: r.bereich,
  erfahrung: r.erfahrung,
  thema: r.thema,
  eingang: r.eingang,
} }));

const cfg = $('Konfiguration').first().json.cfg;

const termine = $('Tabelle termine lesen (Z)').all().map(i => i.json).filter(t => t.termin_id);
termine.sort((a, b) => String(b.erstellt_am).localeCompare(String(a.erstellt_am)));
const termin = termine[0] || { termin_id: 'ohne-termin', titel: 'ohne Termin', datum: '' };
const rows = $('Tabelle rückmeldungen lesen').all().map(i => i.json)
  .filter(r => r.rueckmeldung_id && r.termin_id === termin.termin_id);

const versuch = $runIndex + 1;            // jeder Durchlauf der Schleife erhöht den Zähler
const vorher = versuch > 1 ? $json : null; // beim Wiederholen: Ergebnis der Prüfung
const zeilen = rows.map(r => {
  const aufgaben = String(r.kommentar || '').split(/\r?\n/).filter(Boolean);
  const kopf = `[${r.rueckmeldung_id}] ${r.bereich || 'Bereich offen'} | Erfahrung: ${r.erfahrung || 'unbekannt'} | Hürde: ${r.hindernis || 'keine'} | Thema: ${r.thema || 'ohne'} | Weiter: ${r.antwort}`;
  const punkte = aufgaben.map(a => `    - ${a}`).join('\n');
  return kopf + (punkte ? '\n' + punkte : '') + (r.sonstiges ? `\n    (dazu: ${r.sonstiges})` : '');
});
const liste = zeilen.join('\n') || '(keine Rückmeldungen)';
const alle_aufgaben = rows.flatMap(r => String(r.kommentar || '').split(/\r?\n/).filter(Boolean).map(a => `${a} [${r.rueckmeldung_id}]`));
const system = `Du wertest die Bedarfsabfrage eines Weiterbildungstermins aus. Ziel ist eine Tagesordnung für das nächste Mal, keine Lobhudelei.
Pflicht: Jede Rückmeldung wird mindestens einmal mit ihrer ID in eckigen Klammern belegt, z.B. [R-7K2QF]. Erfinde keine IDs.
Aufbau als HTML ohne <html>-Rahmen:
<h3>Wer im Raum war</h3> Verteilung der Erfahrungsstände in einem Satz.
<h3>Alle genannten Aufgaben</h3> Eine schlichte Liste, eine Aufgabe je Punkt, im Wortlaut der Nennung, jede mit ihrer ID. Nichts weglassen, nichts zusammenfassen. Das ist der Ideenspeicher.
<h3>Was sich wiederholt</h3> Dieselben Aufgaben jetzt zu Gruppen zusammengefasst, die größte Gruppe zuerst, jede mit IDs belegt. Hier wird verdichtet.
<h3>Wer sitzt im Raum</h3> Verteilung nach Bereich, und was die häufigste Hürde ist.
<h3>Gewünschte Themen</h3> Nach Häufigkeit sortiert, mit Anzahl.
<h3>Wie es weitergehen soll</h3> Verteilung der Antworten, und daraus eine Empfehlung in einem Satz.
Sachlich, höchstens \${cfg.max_worte} Wörter, keine Wertungen über Personen, keine Namen. Wenn eine Angabe fehlt, sag das, statt sie zu ergänzen.`;
let user = `Termin: ${termin.titel}${termin.datum ? ' (' + termin.datum + ')' : ''}
Rückmeldungen (je Person eine Kopfzeile, darunter die genannten Aufgaben):
${liste}

Alle Aufgaben als flache Liste, ${alle_aufgaben.length} Stück:
${alle_aufgaben.map(a => '- ' + a).join('\n') || '(keine)'}`;
if (vorher) user += `\n\nKorrektur, Versuch ${versuch}: Im letzten Entwurf fehlten diese IDs: ${vorher.fehlend.join(', ') || 'keine'}. Erfunden waren: ${vorher.erfunden.join(', ') || 'keine'}. Schreibe die Zusammenfassung vollständig neu.`;
return [{ json: { versuch, anzahl: rows.length, system, user } }];

function kiText(j) {
  if (typeof j === 'string') return j;
  for (const k of ['content', 'text', 'output_text', 'message']) {
    const v = j?.[k];
    if (typeof v === 'string') return v;
    if (v && typeof v === 'object' && typeof v.content === 'string') return v.content;
  }
  if (Array.isArray(j?.output)) {
    const t = j.output.flatMap(o => (o.content || [])).map(c => c?.text).filter(Boolean).join('\n');
    if (t) return t;
  }
  return JSON.stringify(j);
}

const cfg = $('Konfiguration').first().json.cfg;

const termine = $('Tabelle termine lesen (Z)').all().map(i => i.json).filter(t => t.termin_id);
termine.sort((a, b) => String(b.erstellt_am).localeCompare(String(a.erstellt_am)));
const termin = termine[0] || { termin_id: 'ohne-termin', titel: 'ohne Termin', datum: '' };
const rows = $('Tabelle rückmeldungen lesen').all().map(i => i.json)
  .filter(r => r.rueckmeldung_id && r.termin_id === termin.termin_id);

const erwartet = rows.map(r => r.rueckmeldung_id);
const text = kiText($json);
const gefunden = [...new Set(text.match(/R-[A-Z0-9]{5}/g) || [])];
const fehlend = erwartet.filter(id => !gefunden.includes(id));
const erfunden = gefunden.filter(id => !erwartet.includes(id));
const versuch = $runIndex + 1;
const vollstaendig = fehlend.length === 0 && erfunden.length === 0;
const entwurf = text.replace(/```html|```/g, '').trim();
const fuss = `<hr><p style="color:#767676;font-size:12px">Automatisch erstellt und geprüft: ${erwartet.length} Rückmeldungen, jede mit ID belegt (Versuch ${versuch}).</p>`;
const lauf_id = 'L-' + Date.now().toString(36).toUpperCase();
return [{ json: {
  vollstaendig, fehlend, erfunden, versuch, max_versuche: cfg.max_versuche,
  lauf_id, termin_id: termin.termin_id, anzahl: erwartet.length,
  betreff: `Zusammenfassung: ${termin.titel}${termin.datum ? ' (' + termin.datum + ')' : ''}`,
  html: entwurf + fuss, entwurf,
} }];
